const now = new Date().toISOString();

// ─── Helper: determine status from HTTP result ───────────────────────────────
function checkResult(nodeItems, nodeName) {
  try {
    const items = $items(nodeName);
    if (!items || items.length === 0) {
      return { status: 'unreachable', detail: 'No response received' };
    }
    const item = items[0];

    // Error output items contain an 'error' field
    if (item.json?.error || item.json?.message?.toLowerCase().includes('error')) {
      return {
        status: 'error',
        detail: item.json?.message || item.json?.error?.message || 'Unknown error'
      };
    }

    return { status: 'ok', detail: null };
  } catch (e) {
    return { status: 'unreachable', detail: e.message };
  }
}

// ─── Supabase DB ─────────────────────────────────────────────────────────────
let supabaseDb = { status: 'ok', detail: null };
try {
  const items = $items('Check: Supabase DB');
  if (!items || items.length === 0 || items[0].json?.error) {
    supabaseDb = { status: 'error', detail: items[0]?.json?.message || 'Query failed' };
  } else {
    // Supabase returns array — if we got any result it is reachable
    const record = Array.isArray(items[0].json) ? items[0].json[0] : items[0].json;
    supabaseDb = {
      status: 'ok',
      detail: record?.created_at
        ? `Last event: ${record.event} at ${record.created_at}`
        : 'Reachable, no records yet'
    };
  }
} catch (e) {
  supabaseDb = { status: 'unreachable', detail: e.message };
}

// ─── Supabase Storage ─────────────────────────────────────────────────────────
let supabaseStorage = { status: 'ok', detail: null };
try {
  const items = $items('Check: Supabase Storage');
  if (!items || items.length === 0 || items[0].json?.error) {
    supabaseStorage = { status: 'error', detail: items[0]?.json?.message || 'Bucket check failed' };
  } else {
    const bucket = items[0].json;
    supabaseStorage = {
      status: 'ok',
      detail: `Bucket "${bucket?.name || 'uploaded-project-docs'}" reachable`
    };
  }
} catch (e) {
  supabaseStorage = { status: 'unreachable', detail: e.message };
}

// ─── ChromaDB Cloud (trychroma.com) ──────────────────────────────────────────
let chromaDb = { status: 'ok', detail: null };
try {
  const items = $items('Check: ChromaDB');
  if (!items || items.length === 0 || items[0].json?.error) {
    chromaDb = {
      status: 'error',
      detail: items[0]?.json?.error || 'Collection check failed'
    };
  } else {
    const collection = items[0].json;

    // trychroma.com returns: { id, name, metadata, tenant, database, count_documents }
    const vectorCount = collection?.count_documents ?? 'unknown';
    const collectionName = collection?.name || 'qa-chunks-batches';
    const database = collection?.database || 'QA-Documents-Chunk';

    chromaDb = {
      status: 'ok',
      detail: `Collection "${collectionName}" in database "${database}" reachable. Vectors: ${vectorCount}`
    };
  }
} catch (e) {
  chromaDb = { status: 'unreachable', detail: e.message };
}

// ─── FastAPI Extractor ────────────────────────────────────────────────────────
let fastapi = { status: 'ok', detail: null };
try {
  const items = $items('Check: FastAPI Extractor');
  if (!items || items.length === 0 || items[0].json?.error) {
    fastapi = { status: 'down', detail: 'FastAPI extractor unreachable at :8000. Run: pm2 start doc-extractor' };
  } else {
    fastapi = {
      status: 'ok',
      detail: items[0].json?.status || 'Reachable at http://127.0.0.1:8000'
    };
  }
} catch (e) {
  fastapi = { status: 'down', detail: e.message };
}

// ─── Converter Service ────────────────────────────────────────────────────────
let converter = { status: 'ok', detail: null };
try {
  const items = $items('Check: Converter Service');
  if (!items || items.length === 0 || items[0].json?.error) {
    converter = { status: 'down', detail: 'Converter service unreachable at :5050. Run: pm2 start format-converter' };
  } else {
    converter = {
      status: 'ok',
      detail: items[0].json?.status || 'Reachable at http://127.0.0.1:5050'
    };
  }
} catch (e) {
  converter = { status: 'down', detail: e.message };
}

// ─── Aggregate overall status ─────────────────────────────────────────────────
const allServices = [supabaseDb, supabaseStorage, chromaDb, fastapi, converter];
const hasError     = allServices.some(s => s.status === 'error');
const hasDown      = allServices.some(s => s.status === 'down');
const hasUnreachable = allServices.some(s => s.status === 'unreachable');

let overallStatus = 'ok';
if (hasDown || hasUnreachable) overallStatus = 'degraded';
if (hasError) overallStatus = 'error';

// ─── Webhooks catalogue ───────────────────────────────────────────────────────
const webhooks = {
  upload:             '/webhook/upload-test-artifacts',
  ingestionStatus:    '/webhook/job-status?jobId=...',
  generate:           '/webhook/generate-qa-doc',
  generationStatus:   '/webhook/job-status-retrieve?jobId=...',
  analytics:          '/webhook/analytics-summary?pipeline=all&days=30',
  health:             '/webhook/health'
};

// ─── Final response ───────────────────────────────────────────────────────────
return [{
  json: {
    status:       overallStatus,
    generatedAt:  now,
    environment:  'n8n',
    services: [
      {
        name:   'n8n backend',
        status: 'ok',
        detail: 'Health workflow executed successfully'
      },
      {
        name:   'Supabase DB',
        status: supabaseDb.status,
        detail: supabaseDb.detail
      },
      {
        name:   'Supabase Storage',
        status: supabaseStorage.status,
        detail: supabaseStorage.detail
      },
      {
        name:   'ChromaDB',
        status: chromaDb.status,
        detail: chromaDb.detail
      },
      {
        name:   'FastAPI Extractor',
        status: fastapi.status,
        detail: fastapi.detail
      },
      {
        name:   'Converter Service',
        status: converter.status,
        detail: converter.detail
      },
      {
        name:   'OpenAI',
        status: 'backend-managed',
        detail: 'Used by vision extraction, embeddings, and generation — not pinged to avoid costs'
      },
      {
        name:   'Confluence',
        status: 'backend-managed',
        detail: 'Used inside generation workflow for document pages'
      },
      {
        name:   'Jira',
        status: 'backend-managed',
        detail: 'Used inside generation workflow for user stories'
      }
    ],
    webhooks,
    integrations: {
      supabaseDb:      supabaseDb.status,
      supabaseStorage: supabaseStorage.status,
      chromaDb:        chromaDb.status,
      fastapiExtractor: fastapi.status,
      converterService: converter.status,
      openai:          'backend-managed',
      jira:            'backend-managed',
      confluence:      'backend-managed'
    }
  }
}];
